import { useReducer } from "react";

export const Reducer = () => {
    const initialValue = { count: 0 };

    const reducer = (state, action) => {
        switch (action.type) {
            case "INCREMENT":
                return { count: state.count + 1 };
            case "DECREMENT":
                return { count: state.count - 1 };
            default:
                return state;
        }
    };

    const [state, dispatch] = useReducer(reducer, initialValue);

    return (
        <div>
            <p>Count: {state.count}</p>
            <button onClick={() => dispatch({ type: 'INCREMENT' })}>INCREMENT</button>
            <button onClick={() => dispatch({ type: 'DECREMENT' })}>DECREMENT</button>
        </div>
    );
};

import { useReducer, useState } from "react";

export const TodoListReducer = () => {
    const initialValue = [];

    const [task, setTask] = useState('');

    const reducer = (state, action) => {
        switch (action.type) {
            case "ADD_TODO":
                return [...state, action.payload];
            case "REMOVE_TODO":
                return state.filter(task => task.taskId !== action.payload.taskId);
            default:
                return state;
        }
    };

    const [state, dispatch] = useReducer(reducer, initialValue);

    return (
        <div>
            <input
                value={task}
                type="text"
                onChange={(e) => setTask(e.target.value)}
            />
            <button onClick={() => {
                 dispatch({ type: 'ADD_TODO', payload: { taskId: Date.now(), task: task } });
                 setTask('');
                }}>Add Todo</button>

            <ul>
                {state.map(task => 
                    <li key={task.taskId}>
                        {task.task}
                        <button onClick={() => dispatch({ type: 'REMOVE_TODO', payload: { taskId: task.taskId } })}>Remove Todo</button>
                    </li>
                )}
            </ul>
        </div>
    );
};

