export const useFetch = ({url}) => {
    const [data, setData] = useState([])
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState('')

    useEffect(() => {
        const fetchData = async () => {
            try {
                const res = await axios.get(url)
                setData(res.data)
                setError('')
            } catch (error) {
                setLoading(false)
                setError(error.message)
            } finally {
                setLoading(false)
